window.SBS_DATA = {"track":{"id":"shell","page":"shell.html","nav":"Command line","langs":["bash"],"default_langs":["bash"]},"concepts":[{"id":"where-am-i","level":"intro","topic":"Navigation","title":"Find your place: pwd, ls, cd"},{"id":"paths","level":"intro","topic":"Navigation","title":"Absolute and relative paths"},{"id":"make-files","level":"intro","topic":"Files","title":"Make files and folders"},{"id":"copy-move-remove","level":"intro","topic":"Files","title":"Copy, move, and remove"},{"id":"read-files","level":"intro","topic":"Files","title":"Read files: cat, head, tail"},{"id":"echo-redirect","level":"intro","topic":"Input and output","title":"echo and redirection"},{"id":"get-help","level":"intro","topic":"Navigation","title":"Get help: --help and man"},{"id":"pipes","level":"intermediate","topic":"Input and output","title":"Pipes"},{"id":"grep","level":"intermediate","topic":"Text","title":"Search text with grep"},{"id":"find","level":"intermediate","topic":"Files","title":"Find files"},{"id":"sort-uniq-wc","level":"intermediate","topic":"Text","title":"Count and sort: wc, sort, uniq"},{"id":"permissions","level":"intermediate","topic":"System","title":"Permissions and chmod"},{"id":"wildcards","level":"intermediate","topic":"Files","title":"Wildcards"},{"id":"variables-env","level":"intermediate","topic":"Scripting","title":"Variables and environment"},{"id":"first-script","level":"advanced","topic":"Scripting","title":"Your first script"},{"id":"script-args","level":"advanced","topic":"Scripting","title":"Script arguments"},{"id":"if-test","level":"advanced","topic":"Scripting","title":"if and test"},{"id":"loops","level":"advanced","topic":"Scripting","title":"for and while loops"},{"id":"functions","level":"advanced","topic":"Scripting","title":"Functions"},{"id":"exit-codes","level":"advanced","topic":"Scripting","title":"Exit codes, && and ||"},{"id":"processes","level":"advanced","topic":"System","title":"Processes and jobs"},{"id":"sed-awk","level":"brilliant","topic":"Text","title":"Edit text with sed and awk"},{"id":"xargs","level":"brilliant","topic":"Input and output","title":"Build commands with xargs"},{"id":"here-docs","level":"brilliant","topic":"Input and output","title":"Here documents"},{"id":"strict-mode","level":"brilliant","topic":"Scripting","title":"Safer scripts: set -euo pipefail and trap"},{"id":"arrays","level":"brilliant","topic":"Scripting","title":"Arrays"},{"id":"path-aliases","level":"brilliant","topic":"System","title":"PATH and aliases"}],"examples":{"bash":{"where-am-i":{"code":"# pwd prints the folder you are in (print working directory).\npwd\n# ls lists what is in the folder.\nls\n# cd changes folders. The prompt shows where you are.\ncd cs\nls\n# .. means the folder above. ~ means your home folder.\ncd ..\npwd","summary":"The command line always works in one folder at a time. pwd shows it, ls lists its contents, and cd moves to another folder.","notes":["The prompt student@linux:~$ shows your user name, the computer name, and the folder you are in.","~ is a short name for your home folder, here /home/student.","cd with no folder name takes you home."],"pitfall":"Folder names are case-sensitive on Linux. cd CS fails with No such file or directory when the folder is named cs.","keywords":["pwd","ls","cd","folder","directory","home","navigate"],"stdin":"","output":"student@linux:~$ pwd\n/home/student\nstudent@linux:~$ ls\ncs  logs  music  notes.txt\nstudent@linux:~$ cd cs\nstudent@linux:~/cs$ ls\ngrades.csv  hello.py  project  roster.txt\nstudent@linux:~/cs$ cd ..\nstudent@linux:~$ pwd\n/home/student","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"paths":{"code":"# An absolute path starts with / and works from any folder.\nls /home/student/cs\n# A relative path starts from the folder you are in now.\ncd music\nls\n# .. is the folder above, so ../cs means \"go up, then into cs\".\nls ../cs/project\n# . is the current folder. ./playlist.txt and playlist.txt name the same file.\nls ./playlist.txt\n# cd works with absolute paths too, from anywhere.\ncd /home/student/cs/project/src\npwd\n# Each .. goes up one level.\ncd ../..\npwd\n# ~ is your home folder, so ~/music works from any folder.\ncd ~/music\n# A relative path that does not exist from here fails.\nls src","summary":"A path tells a command where a file or folder is. An absolute path starts at / and always means the same place. A relative path starts from the folder you are in.","notes":["/home/student/cs/project/src is absolute: it starts at / (the top of the file system) and works no matter where you are.","In ../cs/project, .. means the folder above music, which is /home/student.","~/music is short for /home/student/music, so it works from any folder."],"pitfall":"A relative path depends on where you are. ls src works inside cs/project but fails in music with ls: cannot access 'src': No such file or directory. Run pwd to check where you are.","keywords":["path","absolute path","relative path","..",".","~","home","cd","pwd","parent folder"],"stdin":"","output":"student@linux:~$ ls /home/student/cs\ngrades.csv  hello.py  project  roster.txt\nstudent@linux:~$ cd music\nstudent@linux:~/music$ ls\nplaylist.txt\nstudent@linux:~/music$ ls ../cs/project\nREADME.md  src\nstudent@linux:~/music$ ls ./playlist.txt\n./playlist.txt\nstudent@linux:~/music$ cd /home/student/cs/project/src\nstudent@linux:~/cs/project/src$ pwd\n/home/student/cs/project/src\nstudent@linux:~/cs/project/src$ cd ../..\nstudent@linux:~/cs$ pwd\n/home/student/cs\nstudent@linux:~/cs$ cd ~/music\nstudent@linux:~/music$ ls src\nls: cannot access 'src': No such file or directory","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"make-files":{"code":"# mkdir makes a new folder.\nmkdir projects\nls\n# touch makes an empty file (or updates the time on one that exists).\ntouch projects/todo.txt\nls projects\n# mkdir fails if the folder above the new one does not exist yet.\nmkdir projects/web/css\n# -p makes every missing folder in the path.\nmkdir -p projects/web/css\n# ls -R lists a folder and every folder inside it.\nls -R projects\n# Quote a name that has a space, or touch makes two files.\ntouch \"projects/lab notes.txt\"\nls projects\n# mkdir also fails if the folder already exists.\nmkdir projects","summary":"mkdir makes folders and touch makes empty files. Use them to set up a place for a new project.","notes":["mkdir -p projects/web/css makes web and css in one step, and it does not complain if they already exist.","ls -R shows each folder followed by its contents, so you can check the whole tree at once.","ls shows 'lab notes.txt' in quotes because the name has a space. The quotes are not part of the name."],"pitfall":"touch lab notes.txt without quotes makes two files, lab and notes.txt. Put quotes around names with spaces, or use a dash or underscore instead (lab-notes.txt).","keywords":["mkdir","mkdir -p","touch","new folder","new file","create","directory","ls -R","spaces in names"],"stdin":"","output":"student@linux:~$ mkdir projects\nstudent@linux:~$ ls\ncs  logs  music  notes.txt  projects\nstudent@linux:~$ touch projects/todo.txt\nstudent@linux:~$ ls projects\ntodo.txt\nstudent@linux:~$ mkdir projects/web/css\nmkdir: cannot create directory ‘projects/web/css’: No such file or directory\nstudent@linux:~$ mkdir -p projects/web/css\nstudent@linux:~$ ls -R projects\nprojects:\ntodo.txt  web\n\nprojects/web:\ncss\n\nprojects/web/css:\nstudent@linux:~$ touch \"projects/lab notes.txt\"\nstudent@linux:~$ ls projects\n'lab notes.txt'   todo.txt   web\nstudent@linux:~$ mkdir projects\nmkdir: cannot create directory ‘projects’: File exists","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"copy-move-remove":{"code":"# cp SOURCE DEST makes a copy. The original stays.\ncp notes.txt notes-backup.txt\nls\n# mv moves a file into a folder.\nmkdir old\nmv notes-backup.txt old\n# mv also renames: the \"move\" stays in the same folder with a new name.\nmv old/notes-backup.txt old/notes-week1.txt\nls old\n# cp -r copies a folder and everything in it.\ncp -r music music-copy\n# rm deletes a file. There is no trash can, so it is gone for good.\nrm old/notes-week1.txt\nrm old/notes-week1.txt\n# rm needs -r to delete a folder and its contents.\nrm music-copy\nrm -r music-copy old\nls","summary":"cp copies, mv moves or renames, and rm deletes. Each one takes the source first and the destination second.","notes":["mv old/notes-backup.txt old/notes-week1.txt renames the file, because the folder stays the same and only the name changes.","The second rm old/notes-week1.txt fails with rm: cannot remove 'old/notes-week1.txt': No such file or directory, because the first one already deleted it.","rm -r music-copy old deletes two folders and everything inside them. Check the names before you press Enter."],"pitfall":"rm on a folder fails with rm: cannot remove 'music-copy': Is a directory. Add -r to remove a folder, and be careful: rm does not ask and does not use a trash can.","keywords":["cp","mv","rm","copy","move","rename","delete","remove","cp -r","rm -r","Is a directory"],"stdin":"","output":"student@linux:~$ cp notes.txt notes-backup.txt\nstudent@linux:~$ ls\ncs  logs  music  notes-backup.txt  notes.txt\nstudent@linux:~$ mkdir old\nstudent@linux:~$ mv notes-backup.txt old\nstudent@linux:~$ mv old/notes-backup.txt old/notes-week1.txt\nstudent@linux:~$ ls old\nnotes-week1.txt\nstudent@linux:~$ cp -r music music-copy\nstudent@linux:~$ rm old/notes-week1.txt\nstudent@linux:~$ rm old/notes-week1.txt\nrm: cannot remove 'old/notes-week1.txt': No such file or directory\nstudent@linux:~$ rm music-copy\nrm: cannot remove 'music-copy': Is a directory\nstudent@linux:~$ rm -r music-copy old\nstudent@linux:~$ ls\ncs  logs  music  notes.txt","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"read-files":{"code":"# cat prints a whole file.\ncat notes.txt\n# cat with two files prints one after the other.\ncat cs/hello.py music/playlist.txt\n# head shows the first lines. -n sets how many (the default is 10).\nhead -n 3 logs/server.log\n# tail shows the last lines, where the newest log entries are.\ntail -n 2 logs/server.log\n# head -n 1 on a CSV file shows the column names.\nhead -n 1 cs/grades.csv\n# cat only reads files, not folders.\ncat cs","summary":"cat prints a file, head prints the first lines, and tail prints the last lines. Use head and tail when a file is too long to read at once.","notes":["head and tail show 10 lines unless you give -n with a number.","Log files add new lines at the bottom, so tail shows the most recent events.","For a long file you want to scroll through, use less (press q to quit). It does not run on this page because it waits for keys."],"pitfall":"cat on a folder fails with cat: cs: Is a directory. Use ls to see what is in a folder and cat to read a file.","keywords":["cat","head","tail","head -n","tail -n","read file","print file","less","log","first lines","last lines"],"stdin":"","output":"student@linux:~$ cat notes.txt\nBring calculator Friday.\nCS quiz on loops next Tuesday.\nBand rehearsal moved to 4:15.\nstudent@linux:~$ cat cs/hello.py music/playlist.txt\nprint(\"Hello from Python\")\nSo What - Miles Davis\nTake Five - Dave Brubeck\nBlue in Green - Miles Davis\nMoanin' - Art Blakey\nFootprints - Wayne Shorter\nstudent@linux:~$ head -n 3 logs/server.log\n2026-09-08 08:00:01 INFO server started on port 8080\n2026-09-08 08:02:17 INFO GET /index.html 200\n2026-09-08 08:02:19 WARN slow response /grades 1840ms\nstudent@linux:~$ tail -n 2 logs/server.log\n2026-09-08 08:07:03 INFO GET /grades 200\n2026-09-08 08:09:30 ERROR file not found /missing.html\nstudent@linux:~$ head -n 1 cs/grades.csv\nname,grade,score\nstudent@linux:~$ cat cs\ncat: cs: Is a directory","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"echo-redirect":{"code":"# echo prints its words.\necho Hello, class\n# > sends the output into a file instead of the screen. It creates the file.\necho \"Bring headphones Monday.\" > reminders.txt\ncat reminders.txt\n# >> adds to the end of the file.\necho \"Field trip forms due Friday.\" >> reminders.txt\ncat reminders.txt\n# > replaces everything that was in the file.\necho \"Quiz moved to Tuesday.\" > reminders.txt\ncat reminders.txt\n# Error messages are separate. 2> sends only errors to a file.\nls missing.txt 2> errors.txt\ncat errors.txt","summary":"echo prints text. A redirect sends a command's output into a file: > replaces the file, >> adds to the end, and 2> captures error messages.","notes":["Quotes keep a sentence together as one piece of text and protect characters like ! and ? from the shell.","> creates the file if it does not exist, so you do not need touch first.","ls missing.txt 2> errors.txt prints nothing on screen because the error went into errors.txt."],"pitfall":"Using > when you meant >> erases the file. After echo \"Quiz moved to Tuesday.\" > reminders.txt, the first two reminders are gone and there is no undo.","keywords":["echo","redirect",">",">>","2>","append","overwrite","output to file","stderr","standard error"],"stdin":"","output":"student@linux:~$ echo Hello, class\nHello, class\nstudent@linux:~$ echo \"Bring headphones Monday.\" > reminders.txt\nstudent@linux:~$ cat reminders.txt\nBring headphones Monday.\nstudent@linux:~$ echo \"Field trip forms due Friday.\" >> reminders.txt\nstudent@linux:~$ cat reminders.txt\nBring headphones Monday.\nField trip forms due Friday.\nstudent@linux:~$ echo \"Quiz moved to Tuesday.\" > reminders.txt\nstudent@linux:~$ cat reminders.txt\nQuiz moved to Tuesday.\nstudent@linux:~$ ls missing.txt 2> errors.txt\nstudent@linux:~$ cat errors.txt\nls: cannot access 'missing.txt': No such file or directory","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"get-help":{"code":"# Most commands print their own help with --help.\n# The help for ls is long, so save it to a file and read the top.\nls --help > ls-help.txt\nhead -n 5 ls-help.txt\n# Short commands have short help. Each line lists an option and what it does.\nrmdir --help\n# A wrong option prints a hint that points you to --help.\nls -j\n# type tells you if a command is built into the shell or is a program file.\ntype sort\ntype cd\n# Built-in commands like cd use help instead of --help. -d gives one line.\nhelp -d cd","summary":"When you forget what a command does or which option you need, ask the command itself. --help prints a summary of every option, and help explains commands built into bash.","notes":["In the help text, [OPTION]... means options are optional and you can give more than one. Text in CAPITALS (FILE, DIRECTORY) is a placeholder for your own name.","man ls opens the full manual for ls. It is not installed here and it waits for keys (q quits), but on most Linux computers it is the most complete help.","Once you learn pipes, ls --help | head -n 5 does the first two steps in one command."],"pitfall":"Typing an option that does not exist gives ls: invalid option -- 'j'. Read the Try 'ls --help' line and look up the right letter instead of guessing.","keywords":["--help","help","man","manual","documentation","options","flags","type","builtin","usage","invalid option"],"stdin":"","output":"student@linux:~$ ls --help > ls-help.txt\nstudent@linux:~$ head -n 5 ls-help.txt\nUsage: ls [OPTION]... [FILE]...\nList information about the FILEs (the current directory by default).\nSort entries alphabetically if none of -cftuvSUX nor --sort is specified.\n\nMandatory arguments to long options are mandatory for short options too.\nstudent@linux:~$ rmdir --help\nUsage: rmdir [OPTION]... DIRECTORY...\nRemove the DIRECTORY(ies), if they are empty.\n\n      --ignore-fail-on-non-empty\n                    ignore each failure to remove a non-empty directory\n  -p, --parents     remove DIRECTORY and its ancestors;\n                    e.g., 'rmdir -p a/b' is similar to 'rmdir a/b a'\n\n  -v, --verbose     output a diagnostic for every directory processed\n      --help        display this help and exit\n      --version     output version information and exit\n\nGNU coreutils online help: <https://www.gnu.org/software/coreutils/>\nReport any translation bugs to <https://translationproject.org/team/>\nFull documentation <https://www.gnu.org/software/coreutils/rmdir>\nor available locally via: info '(coreutils) rmdir invocation'\nstudent@linux:~$ ls -j\nls: invalid option -- 'j'\nTry 'ls --help' for more information.\nstudent@linux:~$ type sort\nsort is /usr/bin/sort\nstudent@linux:~$ type cd\ncd is a shell builtin\nstudent@linux:~$ help -d cd\ncd - Change the shell working directory.","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"pipes":{"code":"# | sends the output of the left command into the right command.\ncat music/playlist.txt | head -n 2\n# wc -l counts lines, so this counts the items in cs.\nls cs | wc -l\n# Chain as many commands as you need. Each one works on the last one's output.\ncat cs/roster.txt | sort | head -n 3\n# The last 3 log lines, then the first of those.\ntail -n 3 logs/server.log | head -n 1\n# In a pipe, ls prints one name per line instead of columns.\nls cs\nls cs | cat\n# Errors skip the pipe and go to the screen, so wc counts 0 lines.\nls games | wc -l\n# echo does not read input, so the piped text is ignored.\ncat notes.txt | echo","summary":"A pipe (|) connects two commands: the output of the first becomes the input of the second. Small commands chained with pipes can answer questions no single command can.","notes":["cat cs/roster.txt | sort | head -n 3 runs left to right: read the file, sort the names, keep the first 3.","ls cs | cat prints one name per line. ls checks if its output goes to a screen or a pipe and changes its format.","ls games | wc -l shows the error and then 0, because only normal output goes through the pipe. Error messages go straight to the screen."],"pitfall":"Piping into a command that does not read input does nothing useful. cat notes.txt | echo prints an empty line because echo only prints its arguments.","keywords":["pipe","|","pipeline","chain commands","wc -l","sort","head","tail","standard input","stdin","stdout"],"stdin":"","output":"student@linux:~$ cat music/playlist.txt | head -n 2\nSo What - Miles Davis\nTake Five - Dave Brubeck\nstudent@linux:~$ ls cs | wc -l\n4\nstudent@linux:~$ cat cs/roster.txt | sort | head -n 3\nAva\nAva\nEthan\nstudent@linux:~$ tail -n 3 logs/server.log | head -n 1\n2026-09-08 08:05:47 INFO database connection restored\nstudent@linux:~$ ls cs\ngrades.csv  hello.py  project  roster.txt\nstudent@linux:~$ ls cs | cat\ngrades.csv\nhello.py\nproject\nroster.txt\nstudent@linux:~$ ls games | wc -l\nls: cannot access 'games': No such file or directory\n0\nstudent@linux:~$ cat notes.txt | echo","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"grep":{"code":"# grep PATTERN FILE prints every line that contains the pattern.\ngrep ERROR logs/server.log\n# grep is case-sensitive. -i ignores case.\ngrep miles music/playlist.txt\ngrep -i miles music/playlist.txt\n# -c counts matching lines instead of printing them.\ngrep -c INFO logs/server.log\n# -v prints the lines that do NOT match.\ngrep -v INFO logs/server.log\n# -n adds line numbers. ^ means \"at the start of the line\".\ngrep -n \"^A\" cs/roster.txt\n# -r searches every file in a folder. Each match starts with its file name.\ngrep -ri average cs\n# grep reads from a pipe too.\ncat cs/grades.csv | grep \",10,\" | wc -l","summary":"grep searches text and prints the lines that match a pattern. Use it to find errors in a log, a name in a list, or a word in every file of a project.","notes":["grep miles prints nothing because the file has Miles with a capital M. grep -i miles finds both lines.","\"^A\" is a regular expression: ^ matches the start of a line, so Maya does not match even though it contains a.","In cat cs/grades.csv | grep \",10,\" | wc -l, the commas make 10 match only the grade column, not part of a score like 100. wc -l then counts the 10th graders."],"pitfall":"When grep finds nothing it prints nothing, which looks the same as a command that did not run. Check spelling and capitals, or add -i, before you decide the text is not there.","keywords":["grep","search","find text","pattern","grep -i","grep -v","grep -c","grep -n","grep -r","regex","regular expression","case-insensitive"],"stdin":"","output":"student@linux:~$ grep ERROR logs/server.log\n2026-09-08 08:05:44 ERROR database connection lost\n2026-09-08 08:09:30 ERROR file not found /missing.html\nstudent@linux:~$ grep miles music/playlist.txt\nstudent@linux:~$ grep -i miles music/playlist.txt\nSo What - Miles Davis\nBlue in Green - Miles Davis\nstudent@linux:~$ grep -c INFO logs/server.log\n5\nstudent@linux:~$ grep -v INFO logs/server.log\n2026-09-08 08:02:19 WARN slow response /grades 1840ms\n2026-09-08 08:05:44 ERROR database connection lost\n2026-09-08 08:09:30 ERROR file not found /missing.html\nstudent@linux:~$ grep -n \"^A\" cs/roster.txt\n3:Ava\n9:Ava\nstudent@linux:~$ grep -ri average cs\ncs/project/src/main.py:print(\"Average:\", sum(scores) / len(scores))\ncs/project/README.md:Run src/main.py to print the class average.\nstudent@linux:~$ cat cs/grades.csv | grep \",10,\" | wc -l\n3","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"find":{"code":"# find FOLDER lists everything inside it, at every level.\nfind cs\n# -name matches a file name. Quote the wildcard so find gets it.\nfind . -name \"*.py\"\n# -type d finds folders only. -type f finds files only.\nfind . -type d\n# -iname ignores case.\nfind . -iname \"readme*\"\n# No match prints nothing.\nfind . -name \"*.java\"\n# Without quotes, the shell fills in *.py first. In cs that becomes hello.py,\n# so find looks for files named exactly hello.py and misses main.py.\ncd cs\nfind . -name *.py\nfind . -name \"*.py\"\n# -exec runs a command on each file found. {} is the file name.\nfind . -name \"*.py\" -exec wc -l {} \\;","summary":"find searches a folder and every folder inside it for files that match rules you give it, like a name pattern or a type.","notes":["The first argument is where to start. . means the current folder, so find . searches everything below where you are.","-type d lists folders and -type f lists files. You can combine rules: find . -type f -name \"*.txt\".","In -exec wc -l {} \\; the {} is replaced by each file name, and \\; marks the end of the command."],"pitfall":"find . -name *.py without quotes lets the shell expand *.py first. In cs it finds only ./hello.py and misses ./project/src/main.py. Always quote the pattern: find . -name \"*.py\".","keywords":["find","search files","find -name","find -iname","find -type","find -exec","locate file","recursive","wildcard"],"stdin":"","output":"student@linux:~$ find cs\ncs\ncs/grades.csv\ncs/roster.txt\ncs/project\ncs/project/src\ncs/project/src/main.py\ncs/project/README.md\ncs/hello.py\nstudent@linux:~$ find . -name \"*.py\"\n./cs/project/src/main.py\n./cs/hello.py\nstudent@linux:~$ find . -type d\n.\n./cs\n./cs/project\n./cs/project/src\n./logs\n./music\nstudent@linux:~$ find . -iname \"readme*\"\n./cs/project/README.md\nstudent@linux:~$ find . -name \"*.java\"\nstudent@linux:~$ cd cs\nstudent@linux:~/cs$ find . -name *.py\n./hello.py\nstudent@linux:~/cs$ find . -name \"*.py\"\n./project/src/main.py\n./hello.py\nstudent@linux:~/cs$ find . -name \"*.py\" -exec wc -l {} \\;\n2 ./project/src/main.py\n1 ./hello.py","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"sort-uniq-wc":{"code":"# wc counts lines, words, and characters (bytes).\nwc notes.txt\n# -l counts lines only. The roster has 10 names.\nwc -l cs/roster.txt\n# sort puts lines in alphabetical order.\nsort cs/roster.txt\n# uniq only removes duplicates that are next to each other, so nothing changes here.\nuniq cs/roster.txt | wc -l\n# Sort first, then uniq.\nsort cs/roster.txt | uniq | wc -l\n# -c counts how many times each line appears. -d shows only duplicates.\nsort cs/roster.txt | uniq -c\nsort cs/roster.txt | uniq -d\n# Top 3 scores: skip the header, sort by the 3rd comma column as numbers, highest first.\ntail -n +2 cs/grades.csv | sort -t, -k3 -n -r | head -n 3\n# How many students in each grade level.\ntail -n +2 cs/grades.csv | cut -d, -f2 | sort | uniq -c","summary":"wc counts, sort orders lines, and uniq removes repeated lines. Together they answer questions like \"how many different names?\" and \"who scored highest?\"","notes":["wc notes.txt prints 3 numbers before the name: lines, words, and bytes.","In sort -t, -k3 -n -r, -t, splits on commas, -k3 sorts by the 3rd column, -n compares as numbers, and -r reverses so the highest is first.","tail -n +2 starts at line 2, which skips the header row name,grade,score. cut -d, -f2 keeps only the 2nd column."],"pitfall":"uniq without sort misses duplicates that are not next to each other. uniq cs/roster.txt still has 10 lines because the second Ava and Leo are at the end. Use sort | uniq.","keywords":["wc","wc -l","sort","sort -n","sort -r","sort -k","uniq","uniq -c","uniq -d","count","duplicates","cut","top scores"],"stdin":"","output":"student@linux:~$ wc notes.txt\n 3 14 86 notes.txt\nstudent@linux:~$ wc -l cs/roster.txt\n10 cs/roster.txt\nstudent@linux:~$ sort cs/roster.txt\nAva\nAva\nEthan\nLeo\nLeo\nLucas\nMaya\nMia\nNoah\nSofia\nstudent@linux:~$ uniq cs/roster.txt | wc -l\n10\nstudent@linux:~$ sort cs/roster.txt | uniq | wc -l\n8\nstudent@linux:~$ sort cs/roster.txt | uniq -c\n      2 Ava\n      1 Ethan\n      2 Leo\n      1 Lucas\n      1 Maya\n      1 Mia\n      1 Noah\n      1 Sofia\nstudent@linux:~$ sort cs/roster.txt | uniq -d\nAva\nLeo\nstudent@linux:~$ tail -n +2 cs/grades.csv | sort -t, -k3 -n -r | head -n 3\nNoah,12,95\nMaya,10,92\nEthan,10,88\nstudent@linux:~$ tail -n +2 cs/grades.csv | cut -d, -f2 | sort | uniq -c\n      3 10\n      3 11\n      2 12","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"permissions":{"code":"# ls -l shows permissions first: - for a file (d for a folder), then\n# rwx for the owner, the group, and everyone else.\nls -l notes.txt\nls -ld cs\n# greet.sh is a script, but nobody has x (execute) permission yet.\ncat greet.sh\nls -l greet.sh\n./greet.sh\n# chmod +x adds execute permission.\nchmod +x greet.sh\nls -l greet.sh\n./greet.sh\n# chmod 644 sets exact permissions with numbers: 6 = rw- for you, 4 = r-- for others.\nchmod 644 greet.sh\nls -l greet.sh\n# bash greet.sh runs the script without the execute bit.\nbash greet.sh","summary":"Every file has an owner and permissions that say who can read (r), write (w), and execute (x) it. chmod changes them. A script needs x before you can run it as ./script.","notes":["-rw-r--r-- 1 student student reads as: a file; the owner (student) can read and write; the group and everyone else can only read.","In numbers, r = 4, w = 2, x = 1, added up for owner, group, others. 755 is rwxr-xr-x (a script) and 644 is rw-r--r-- (a normal file).","bash greet.sh works even without x because bash is the program being run, and it only needs to read the file."],"pitfall":"Running a script without the execute bit fails with Permission denied (in your own terminal: bash: ./greet.sh: Permission denied). Run chmod +x greet.sh once and try again.","keywords":["chmod","chmod +x","chmod 644","chmod 755","permissions","ls -l","rwx","execute","Permission denied","owner","group"],"stdin":"","output":"student@linux:~$ ls -l notes.txt\n-rw-r--r-- 1 student student 86 Sep  8 08:15 notes.txt\nstudent@linux:~$ ls -ld cs\ndrwxr-xr-x 3 student student 4096 Sep  8 08:15 cs\nstudent@linux:~$ cat greet.sh\n#!/bin/bash\necho \"Hello from greet.sh\"\nstudent@linux:~$ ls -l greet.sh\n-rw-r--r-- 1 student student 39 Sep  8 08:15 greet.sh\nstudent@linux:~$ ./greet.sh\nbash: ./greet.sh: Permission denied\nstudent@linux:~$ chmod +x greet.sh\nstudent@linux:~$ ls -l greet.sh\n-rwxr-xr-x 1 student student 39 Sep  8 08:15 greet.sh\nstudent@linux:~$ ./greet.sh\nHello from greet.sh\nstudent@linux:~$ chmod 644 greet.sh\nstudent@linux:~$ ls -l greet.sh\n-rw-r--r-- 1 student student 39 Sep  8 08:15 greet.sh\nstudent@linux:~$ bash greet.sh\nHello from greet.sh","run":true,"shot":null,"shot_note":"","setup_note":"Starts with a two-line script named greet.sh that does not have execute permission.","preview_height":null,"mode":"session","filename":null},"wildcards":{"code":"# * matches any characters. The shell replaces the pattern with matching names.\nls *.txt\nls cs/*.py\n# */ looks one folder down: every .txt file in any folder.\nls */*.txt\n# ? matches exactly one character. -d lists the folder itself, not what is in it.\nls -d ?s\n# [gr]* matches names that start with g or r.\nls cs/[gr]*\n# echo shows what the shell turns a pattern into before the command runs.\necho cs/*\n# Wildcards work with any command, like cp.\nmkdir backup\ncp cs/*.csv cs/*.txt backup\nls backup\n# If nothing matches, the pattern is left as typed, and ls looks for a file named *.mp3.\nls music/*.mp3","summary":"Wildcards let you name many files with one pattern. * matches any characters, ? matches one character, and [abc] matches one character from a list.","notes":["The shell expands the pattern before the command runs, so ls never sees *.txt. It receives the list of matching names.","ls */*.txt finds cs/roster.txt and music/playlist.txt but not notes.txt, because the pattern requires a folder first.","* does not match names that start with a dot (hidden files like .bashrc). Use ls -a to see those."],"pitfall":"A pattern with no matches is passed as typed. ls music/*.mp3 fails with ls: cannot access 'music/*.mp3': No such file or directory, which means no file matched.","keywords":["wildcard","glob","*","?","[ ]","pattern","globbing","all files","*.txt","expansion"],"stdin":"","output":"student@linux:~$ ls *.txt\nnotes.txt\nstudent@linux:~$ ls cs/*.py\ncs/hello.py\nstudent@linux:~$ ls */*.txt\ncs/roster.txt  music/playlist.txt\nstudent@linux:~$ ls -d ?s\ncs\nstudent@linux:~$ ls cs/[gr]*\ncs/grades.csv  cs/roster.txt\nstudent@linux:~$ echo cs/*\ncs/grades.csv cs/hello.py cs/project cs/roster.txt\nstudent@linux:~$ mkdir backup\nstudent@linux:~$ cp cs/*.csv cs/*.txt backup\nstudent@linux:~$ ls backup\ngrades.csv  roster.txt\nstudent@linux:~$ ls music/*.mp3\nls: cannot access 'music/*.mp3': No such file or directory","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"variables-env":{"code":"# Set a variable with name=value. No spaces around =.\nname=Maya\n# $name reads it. Double quotes fill in variables.\necho \"Hello, $name\"\n# Single quotes print exactly what you type.\necho 'Hello, $name'\n# Use ${name} when letters come right after the variable.\nscore=92\necho \"Score: ${score}pts\"\n# $(command) saves a command's output in a variable.\ncount=$(wc -l < cs/roster.txt)\necho \"The roster has $count names\"\n# Environment variables are set for you. Names are in capitals by tradition.\necho \"$USER lives in $HOME\"\n# A new bash program (a child) does not see a plain variable...\nbash -c 'echo \"Child sees: $name\"'\n# ...until you export it.\nexport name\nbash -c 'echo \"Child sees: $name\"'","summary":"A variable stores text under a name so you can reuse it. Environment variables like HOME and USER are set for you, and export passes your own variables to programs you start.","notes":["wc -l < cs/roster.txt prints only the number. Without the <, wc also prints the file name.","bash -c '...' starts a new bash program. Single quotes keep $name from being filled in early, so the child shell reads it.","printenv lists every environment variable. PATH, HOME, and USER are the ones you will use most."],"pitfall":"name = Maya with spaces fails with name: command not found, because bash reads name as a command and = and Maya as its arguments. Write name=Maya with no spaces.","keywords":["variable","$","export","environment","env","printenv","HOME","USER","command substitution","$( )","quotes","single quotes","double quotes"],"stdin":"","output":"student@linux:~$ name=Maya\nstudent@linux:~$ echo \"Hello, $name\"\nHello, Maya\nstudent@linux:~$ echo 'Hello, $name'\nHello, $name\nstudent@linux:~$ score=92\nstudent@linux:~$ echo \"Score: ${score}pts\"\nScore: 92pts\nstudent@linux:~$ count=$(wc -l < cs/roster.txt)\nstudent@linux:~$ echo \"The roster has $count names\"\nThe roster has 10 names\nstudent@linux:~$ echo \"$USER lives in $HOME\"\nstudent lives in /home/student\nstudent@linux:~$ bash -c 'echo \"Child sees: $name\"'\nChild sees: \nstudent@linux:~$ export name\nstudent@linux:~$ bash -c 'echo \"Child sees: $name\"'\nChild sees: Maya","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"first-script":{"code":"#!/bin/bash\n# The first line (the shebang) tells Linux to run this file with bash.\n# A script is a list of commands that run in order, top to bottom,\n# exactly as if you typed them at the prompt.\n\necho \"Class files report\"\necho \"Folder: $(pwd)\"\n\n# Paths in a script are relative to where you RUN it, not where the file is.\necho \"Students on roster: $(wc -l < cs/roster.txt)\"\necho \"Songs in playlist: $(wc -l < music/playlist.txt)\"\necho \"Errors in server log: $(grep -c ERROR logs/server.log)\"\necho \"Report done\"","summary":"A script is a text file of commands that bash runs in order. Write the steps once, then run them any time with one command.","notes":["#!/bin/bash must be the very first line. It tells Linux which program reads the rest of the file.","./report.sh means \"report.sh in this folder\". bash report.sh also works, and it does not need the execute bit.","Run from music, the script looks for music/cs/roster.txt, which does not exist, so those lines fail. The script keeps going after each error and still prints Report done."],"pitfall":"Typing report.sh without ./ fails with report.sh: command not found. Bash only looks for commands in the folders listed in PATH, not in the current folder.","keywords":["script","shell script","bash script","shebang","#!/bin/bash",".sh","run script","./","chmod +x"],"stdin":"","output":"student@linux:~$ ls -l report.sh\n-rwxr-xr-x 1 student student 513 Sep  8 08:15 report.sh\nstudent@linux:~$ ./report.sh\nClass files report\nFolder: /home/student\nStudents on roster: 10\nSongs in playlist: 5\nErrors in server log: 2\nReport done\nstudent@linux:~$ cd music\nstudent@linux:~/music$ ../report.sh\nClass files report\nFolder: /home/student/music\n../report.sh: line 10: cs/roster.txt: No such file or directory\nStudents on roster: \n../report.sh: line 11: music/playlist.txt: No such file or directory\nSongs in playlist: \ngrep: logs/server.log: No such file or directory\nErrors in server log: \nReport done","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"report.sh"},"script-args":{"code":"#!/bin/bash\n# Usage: ./shoutout.sh NAME [EVENT]\n# Words typed after the script name are its arguments: $1, $2, and so on.\n\necho \"Script name: $0\"\necho \"Number of arguments: $#\"\necho \"All arguments: $*\"\n\n# ${1:-everyone} means: use $1, or \"everyone\" if $1 is missing or empty.\nname=\"${1:-everyone}\"\nevent=\"${2:-band rehearsal}\"\necho \"Great job at $event, $name!\"\n\n# shift drops $1 and moves every argument down one place.\nshift\necho \"After shift: $# left ($*)\"","summary":"Arguments are the words you type after a script's name. Inside the script, $1 is the first, $2 the second, $# is how many there are, and $@ or $* is all of them.","notes":["\"the CS quiz\" is in quotes, so it arrives as one argument ($2). Without quotes it would be three.","./shoutout.sh Ava Smith gives 2 arguments, so Smith becomes the event. \"Ava Smith\" in quotes is 1 argument.","$0 is the name you used to run the script, here ./shoutout.sh. shift with no arguments left does nothing."],"pitfall":"Forgetting quotes around an argument with spaces splits it. ./shoutout.sh Ava Smith prints Great job at Smith, Ava! because Smith became $2.","keywords":["arguments","parameters","$1","$2","$#","$@","$*","$0","shift","default value","${1:-}","command line arguments"],"stdin":"","output":"student@linux:~$ ./shoutout.sh Maya \"the CS quiz\"\nScript name: ./shoutout.sh\nNumber of arguments: 2\nAll arguments: Maya the CS quiz\nGreat job at the CS quiz, Maya!\nAfter shift: 1 left (the CS quiz)\nstudent@linux:~$ ./shoutout.sh Leo\nScript name: ./shoutout.sh\nNumber of arguments: 1\nAll arguments: Leo\nGreat job at band rehearsal, Leo!\nAfter shift: 0 left ()\nstudent@linux:~$ ./shoutout.sh\nScript name: ./shoutout.sh\nNumber of arguments: 0\nAll arguments: \nGreat job at band rehearsal, everyone!\nAfter shift: 0 left ()\nstudent@linux:~$ ./shoutout.sh Ava Smith\nScript name: ./shoutout.sh\nNumber of arguments: 2\nAll arguments: Ava Smith\nGreat job at Smith, Ava!\nAfter shift: 1 left (Smith)\nstudent@linux:~$ ./shoutout.sh \"Ava Smith\"\nScript name: ./shoutout.sh\nNumber of arguments: 1\nAll arguments: Ava Smith\nGreat job at band rehearsal, Ava Smith!\nAfter shift: 0 left ()","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"shoutout.sh"},"if-test":{"code":"#!/bin/bash\n# Usage: ./grade.sh NAME\n# Looks up a student in cs/grades.csv and prints a letter grade.\nname=\"$1\"\n\n# -z is true when a string is empty (no argument given).\nif [ -z \"$name\" ]; then\n  echo \"Usage: ./grade.sh NAME\"\n  exit 1\nfi\n\n# -f is true when a file exists. ! flips true and false.\nif [ ! -f cs/grades.csv ]; then\n  echo \"Missing cs/grades.csv\"\n  exit 1\nfi\n\n# cut -d, -f3 keeps the 3rd comma-separated column (the score).\nscore=$(grep \"^$name,\" cs/grades.csv | cut -d, -f3)\nif [ -z \"$score\" ]; then\n  echo \"$name is not in grades.csv\"\n  exit 1\nfi\n\n# Numbers use -ge (>=), -gt (>), -lt (<), -le (<=), -eq (=), -ne (not =).\nif [ \"$score\" -ge 90 ]; then\n  letter=\"A\"\nelif [ \"$score\" -ge 80 ]; then\n  letter=\"B\"\nelif [ \"$score\" -ge 70 ]; then\n  letter=\"C\"\nelse\n  letter=\"F\"\nfi\necho \"$name: $score ($letter)\"\n\n# Strings use = and !=. Spaces inside [ ] are required.\nif [ \"$letter\" = \"F\" ]; then\n  echo \"Reminder: tutoring is Tuesday after school.\"\nfi","summary":"if runs commands only when a test is true. [ ] (the test command) compares numbers and strings and checks files, and elif and else handle the other cases.","notes":["[ \"$score\" -ge 90 ] compares numbers. For strings use =, as in [ \"$letter\" = \"F\" ].","Every if ends with fi, and then goes on the same line as the test after a semicolon: if [ ... ]; then.","Put variables in double quotes inside [ ]. If $name is empty, [ -z \"$name\" ] still works, but [ -z $name ] can break."],"pitfall":"Leaving out the spaces breaks the test. [\"$score\" -ge 90] fails with [92: command not found, because [ is a command and needs spaces around it like any other command.","keywords":["if","then","else","elif","fi","test","[ ]","[[ ]]","-eq","-ge","-gt","-lt","-z","-f","-d","compare","condition"],"stdin":"","output":"student@linux:~$ ./grade.sh Noah\nNoah: 95 (A)\nstudent@linux:~$ ./grade.sh Leo\nLeo: 78 (C)\nstudent@linux:~$ ./grade.sh Lucas\nLucas: 83 (B)\nstudent@linux:~$ ./grade.sh Sofia\nSofia: 64 (F)\nReminder: tutoring is Tuesday after school.\nstudent@linux:~$ ./grade.sh Zoe\nZoe is not in grades.csv\nstudent@linux:~$ ./grade.sh\nUsage: ./grade.sh NAME","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"grade.sh"},"loops":{"code":"#!/bin/bash\n# for runs the loop body once for each word in the list.\nfor folder in cs logs music; do\n  echo \"$folder has $(ls \"$folder\" | wc -l) items\"\ndone\n\n# A wildcard gives the loop a list of file names.\nfor file in cs/*.py; do\n  echo \"Python file: $file\"\ndone\n\n# If nothing matches, the pattern itself is the only item.\nfor file in cs/*.java; do\n  echo \"Java file: $file\"\ndone\n\n# C-style for counts with a number.\nfor (( i = 3; i >= 1; i-- )); do\n  echo \"Countdown: $i\"\ndone\n\n# while read reads a file one line at a time.\n# IFS=, splits each line at commas into the three variables.\nhonor=0\nwhile IFS=, read -r name grade score; do\n  # Skip the header row.\n  if [ \"$name\" = \"name\" ]; then\n    continue\n  fi\n  if [ \"$score\" -ge 85 ]; then\n    echo \"Honor roll: $name ($score)\"\n    honor=$((honor + 1))\n  fi\ndone < cs/grades.csv\necho \"Honor roll total: $honor\"\n\n# while with a condition: keep going until the test is false.\nsongs=0\nwhile [ $songs -lt 2 ]; do\n  songs=$((songs + 1))\n  echo \"Playing song $songs\"\ndone","summary":"A for loop repeats commands once for each item in a list. A while loop repeats as long as a test is true, and while read goes through a file line by line.","notes":["for file in cs/*.java runs once with the text cs/*.java, because no file matched. Check with [ -e \"$file\" ] if that can happen.","done < cs/grades.csv feeds the file into the whole while loop, so read gets the next line each time around.","$((honor + 1)) does whole-number math. The loop body runs between do and done."],"pitfall":"Piping into a while loop (cat cs/grades.csv | while read ...) runs the loop in a separate shell, so honor is still 0 after done. Use done < cs/grades.csv instead.","keywords":["for","while","loop","do","done","while read","IFS","continue","break","for in","C-style for","iterate","read file line by line"],"stdin":"","output":"student@linux:~$ ./loops.sh\ncs has 4 items\nlogs has 1 items\nmusic has 1 items\nPython file: cs/hello.py\nJava file: cs/*.java\nCountdown: 3\nCountdown: 2\nCountdown: 1\nHonor roll: Maya (92)\nHonor roll: Ava (88)\nHonor roll: Noah (95)\nHonor roll: Ethan (88)\nHonor roll total: 4\nPlaying song 1\nPlaying song 2","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"loops.sh"},"functions":{"code":"#!/bin/bash\n# A function must be defined before the line that calls it.\n# Arguments arrive as $1, $2, ... just like a script's arguments.\nletter_grade() {\n  local score=$1\n  if [ \"$score\" -ge 90 ]; then\n    echo \"A\"\n  elif [ \"$score\" -ge 80 ]; then\n    echo \"B\"\n  elif [ \"$score\" -ge 70 ]; then\n    echo \"C\"\n  else\n    echo \"F\"\n  fi\n}\n\n# To return a value, echo it and capture it with $(...).\nreport() {\n  local name=$1\n  local score=$2\n  echo \"$name: $score ($(letter_grade \"$score\"))\"\n}\n\n# return sets an exit code (0 = true), so the function works in an if.\nis_passing() {\n  [ \"$1\" -ge 70 ]\n}\n\n# \"$@\" is every argument; $# is how many.\naverage() {\n  local total=0\n  for s in \"$@\"; do\n    total=$((total + s))\n  done\n  echo $((total / $#))\n}\n\n# Call a function like a command: name, then arguments.\nreport Maya 92\nreport Leo 78\nreport Sofia 64\necho \"Average: $(average 92 78 88 95 64)\"\n\nif is_passing 64; then\n  echo \"64 passes\"\nelse\n  echo \"64 does not pass\"\nfi\n\n# local keeps a variable inside its function. This total was never changed.\ntotal=\"not set\"\naverage 90 80 > /dev/null\necho \"total after average: $total\"","summary":"A function gives a name to a group of commands so you can run them many times with different arguments. Bash functions return text with echo and success or failure with an exit code.","notes":["average prints 83, not 83.4, because $(( )) only does whole-number math and drops the decimal part.","is_passing has no echo. The exit code of its last command, [ \"$1\" -ge 70 ], is what if checks.","local total inside average is a separate variable, so the total=\"not set\" outside the function is unchanged."],"pitfall":"return only sets an exit code from 0 to 255. return 92 does not give you 92 in a variable. Use echo inside the function and result=$(letter_grade 92) outside.","keywords":["function","functions","local","return","echo","$@","$#","arguments","define function","call function","exit code"],"stdin":"","output":"student@linux:~$ ./grades.sh\nMaya: 92 (A)\nLeo: 78 (C)\nSofia: 64 (F)\nAverage: 83\n64 does not pass\ntotal after average: not set","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"grades.sh"},"exit-codes":{"code":"#!/bin/bash\n# Usage: ./check-log.sh LOGFILE\n# Exit codes: 0 = no errors, 1 = errors found, 2 = no such file.\nlog=\"$1\"\n\n# || runs the right side only if the left side fails.\n[ -f \"$log\" ] || { echo \"No such log: $log\"; exit 2; }\n\n# $? holds the exit code of the last command. grep -q prints nothing:\n# it exits 0 if it found a match and 1 if it did not.\ngrep -q ERROR \"$log\"\nstatus=$?\necho \"grep exit code: $status\"\n\nif [ $status -eq 0 ]; then\n  echo \"Errors in $log:\"\n  grep ERROR \"$log\"\n  exit 1\nfi\n\n# && runs the next command only if the one before it worked.\nmkdir -p checked && cp \"$log\" checked/ && echo \"No errors. Copied $log to checked/\"","summary":"Every command ends with an exit code: 0 means success and any other number means failure. && and || use that code to decide whether to run the next command, and exit sets your script's own code.","notes":["In the session, ./check-log.sh logs/server.log; echo \"Exit code: $?\" runs both commands on one line so $? is the script's code.","./check-log.sh logs/today.log && echo \"Safe to archive\" prints the message only because the script exited with 0.","{ echo ...; exit 2; } groups two commands so both run when the test fails. The spaces and the last ; are required."],"pitfall":"$? changes after every command, even echo. Save it right away (status=$?) if you need it more than once, or the second check reads echo's 0.","keywords":["exit code","exit status","$?","exit","&&","||","and","or","return code","grep -q","success","failure"],"stdin":"","output":"student@linux:~$ ./check-log.sh logs/server.log; echo \"Exit code: $?\"\ngrep exit code: 0\nErrors in logs/server.log:\n2026-09-08 08:05:44 ERROR database connection lost\n2026-09-08 08:09:30 ERROR file not found /missing.html\nExit code: 1\nstudent@linux:~$ echo \"2026-09-09 08:00:00 INFO server started\" > logs/today.log\nstudent@linux:~$ ./check-log.sh logs/today.log && echo \"Safe to archive\"\ngrep exit code: 1\nNo errors. Copied logs/today.log to checked/\nSafe to archive\nstudent@linux:~$ ls checked\ntoday.log\nstudent@linux:~$ ./check-log.sh logs/old.log || echo \"Check failed\"\nNo such log: logs/old.log\nCheck failed\nstudent@linux:~$ ./check-log.sh logs/old.log; echo \"Exit code: $?\"\nNo such log: logs/old.log\nExit code: 2","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"check-log.sh"},"processes":{"code":"# & at the end runs a command in the background, so the prompt comes back right away.\nsleep 30 &\nsleep 60 &\n# jobs lists the background jobs this shell started. + is the newest.\njobs\n# ps lists running processes. -o comm= shows only the command names.\nps -o comm=\n# kill %1 stops job number 1.\nkill %1\njobs\nkill %2\njobs\nps -o comm=\n# timeout stops a command that runs too long. Exit code 124 means it was stopped.\ntimeout 2 sleep 10; echo \"Exit code: $?\"\n# A command without & makes you wait until it finishes.\nsleep 1; echo \"Done waiting\"","summary":"Every running program is a process. You can start a command in the background with &, list your jobs, and stop one with kill.","notes":["In your own terminal, sleep 30 & also prints a line like [1] 4821: the job number and the process ID (PID). PIDs change every run, so this page hides them.","kill %1 uses the job number. kill 4821 uses a PID, which you can find with ps or pgrep sleep.","Press Ctrl+C to stop a command running in the foreground, and fg to bring a background job back to the front."],"pitfall":"kill 1 without the % sends the signal to process ID 1, not job 1, and fails with kill: (1) - Operation not permitted. Write kill %1 for a job number.","keywords":["process","processes","jobs","background","&","kill","ps","fg","bg","Ctrl+C","timeout","PID","sleep","pgrep"],"stdin":"","output":"student@linux:~$ sleep 30 &\nstudent@linux:~$ sleep 60 &\nstudent@linux:~$ jobs\n[1]-  Running                 sleep 30 &\n[2]+  Running                 sleep 60 &\nstudent@linux:~$ ps -o comm=\nbash\nsleep\nsleep\nps\nstudent@linux:~$ kill %1\nstudent@linux:~$ jobs\n[2]+  Running                 sleep 60 &\nstudent@linux:~$ kill %2\nstudent@linux:~$ jobs\nstudent@linux:~$ ps -o comm=\nbash\nps\nstudent@linux:~$ timeout 2 sleep 10; echo \"Exit code: $?\"\nExit code: 124\nstudent@linux:~$ sleep 1; echo \"Done waiting\"\nDone waiting","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"sed-awk":{"code":"# sed 's/old/new/' replaces the first match on each line and prints the result.\nsed 's/Miles Davis/Miles Dewey Davis/' music/playlist.txt\n# The file itself did not change.\nhead -n 1 music/playlist.txt\n# -i edits the file in place.\nsed -i 's/Friday/Thursday/' notes.txt\ncat notes.txt\n# /g replaces every match on the line, not only the first.\nhead -n 3 cs/grades.csv | sed 's/,/ | /g'\n# -n with p prints only the lines you name, here lines 4 to 5.\nsed -n '4,5p' logs/server.log\n# awk splits each line into fields: $1, $2, ... -F, splits at commas.\n# NR is the line number, so NR > 1 skips the header.\nawk -F, 'NR > 1 && $3 >= 90 {print $1, $3}' cs/grades.csv\n# END runs once after the last line.\nawk -F, 'NR > 1 {sum += $3; n++} END {print \"Average:\", sum / n}' cs/grades.csv\n# Without -F, awk splits at spaces. $3 in the log is the level.\nawk '{print $3}' logs/server.log | sort | uniq -c","summary":"sed edits text line by line, most often to find and replace. awk splits each line into fields (columns) and runs a small program on them, which makes it good for reports from CSV files and logs.","notes":["Without -i, sed prints the changed text and leaves the file alone. With -i it rewrites the file, and there is no undo.","In awk, {print $1, $3} runs for every line that matches the pattern before it. The comma in print adds a space.","awk does decimal math, so the average prints 82.375. Bash $(( )) would give 82."],"pitfall":"Using double quotes around an awk program lets bash replace $1 and $3 before awk sees them, so awk prints the wrong fields or nothing. Put awk programs in single quotes.","keywords":["sed","awk","find and replace","substitute","s///","sed -i","sed -n","fields","columns","-F","NR","END","csv","report"],"stdin":"","output":"student@linux:~$ sed 's/Miles Davis/Miles Dewey Davis/' music/playlist.txt\nSo What - Miles Dewey Davis\nTake Five - Dave Brubeck\nBlue in Green - Miles Dewey Davis\nMoanin' - Art Blakey\nFootprints - Wayne Shorter\nstudent@linux:~$ head -n 1 music/playlist.txt\nSo What - Miles Davis\nstudent@linux:~$ sed -i 's/Friday/Thursday/' notes.txt\nstudent@linux:~$ cat notes.txt\nBring calculator Thursday.\nCS quiz on loops next Tuesday.\nBand rehearsal moved to 4:15.\nstudent@linux:~$ head -n 3 cs/grades.csv | sed 's/,/ | /g'\nname | grade | score\nMaya | 10 | 92\nLeo | 11 | 78\nstudent@linux:~$ sed -n '4,5p' logs/server.log\n2026-09-08 08:05:44 ERROR database connection lost\n2026-09-08 08:05:45 INFO retrying database connection\nstudent@linux:~$ awk -F, 'NR > 1 && $3 >= 90 {print $1, $3}' cs/grades.csv\nMaya 92\nNoah 95\nstudent@linux:~$ awk -F, 'NR > 1 {sum += $3; n++} END {print \"Average:\", sum / n}' cs/grades.csv\nAverage: 82.375\nstudent@linux:~$ awk '{print $3}' logs/server.log | sort | uniq -c\n      2 ERROR\n      5 INFO\n      1 WARN","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"xargs":{"code":"# xargs reads words from its input and adds them to the end of a command.\n# -t prints each command before it runs.\necho \"quiz1.txt quiz2.txt quiz3.txt\" | xargs -t touch\nls\n# find prints file names; xargs turns them into arguments for wc.\nfind cs -name \"*.py\" | xargs wc -l\n# -n 1 runs the command once per word.\nhead -n 3 cs/roster.txt | xargs -n 1 echo \"Student:\"\n# -I {} puts each input line where {} is, instead of at the end.\nls quiz*.txt | xargs -I {} cp {} {}.bak\nls quiz*\n# xargs splits on spaces, so a name with a space breaks into two.\ntouch \"lab report.txt\"\nls lab*.txt | xargs rm\n# -d '\\n' splits on new lines only, so the whole name stays together.\nls lab*.txt | xargs -d '\\n' rm\nls *.txt","summary":"xargs turns lines of input into arguments for another command. Use it when a command like rm, touch, or wc takes file names as arguments but you have the names as output from find, ls, or grep.","notes":["wc -l does not read file names from a pipe. find cs -name \"*.py\" | xargs wc -l runs wc -l with both names, so it counts lines in each file and prints a total.","With -I {}, xargs runs the command once per line: cp quiz1.txt quiz1.txt.bak, then quiz2, then quiz3.","find has its own safe version: find . -name \"*.bak\" -print0 | xargs -0 rm handles any file name, even ones with spaces or new lines."],"pitfall":"File names with spaces split into two arguments. ls lab*.txt | xargs rm tries to remove lab and report.txt and fails with rm: cannot remove 'lab': No such file or directory.","keywords":["xargs","xargs -n","xargs -I","xargs -0","xargs -t","find","arguments","pipe to command","batch","-print0"],"stdin":"","output":"student@linux:~$ echo \"quiz1.txt quiz2.txt quiz3.txt\" | xargs -t touch\ntouch quiz1.txt quiz2.txt quiz3.txt\nstudent@linux:~$ ls\ncs  logs  music  notes.txt  quiz1.txt  quiz2.txt  quiz3.txt\nstudent@linux:~$ find cs -name \"*.py\" | xargs wc -l\n  2 cs/project/src/main.py\n  1 cs/hello.py\n  3 total\nstudent@linux:~$ head -n 3 cs/roster.txt | xargs -n 1 echo \"Student:\"\nStudent: Maya\nStudent: Leo\nStudent: Ava\nstudent@linux:~$ ls quiz*.txt | xargs -I {} cp {} {}.bak\nstudent@linux:~$ ls quiz*\nquiz1.txt  quiz1.txt.bak  quiz2.txt  quiz2.txt.bak  quiz3.txt  quiz3.txt.bak\nstudent@linux:~$ touch \"lab report.txt\"\nstudent@linux:~$ ls lab*.txt | xargs rm\nrm: cannot remove 'lab': No such file or directory\nrm: cannot remove 'report.txt': No such file or directory\nstudent@linux:~$ ls lab*.txt | xargs -d '\\n' rm\nstudent@linux:~$ ls *.txt\nnotes.txt  quiz1.txt  quiz2.txt  quiz3.txt","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null},"here-docs":{"code":"#!/bin/bash\n# Usage: ./welcome.sh NAME\nname=\"${1:-Maya}\"\ncount=$(wc -l < cs/roster.txt)\n\n# cat << EOF sends every line up to EOF into cat.\n# $variables and $(commands) inside are filled in.\ncat << EOF\nWelcome to CS, $name!\nStudents on the roster: $count\nFirst file to open: $(ls cs/*.py)\nEOF\n\n# Quote the marker ('EOF') to keep $ signs exactly as typed.\ncat << 'EOF'\nLab fee: $5. Type $name in your own script to use a variable.\nEOF\n\n# Redirect a here document into a file to write several lines at once.\ncat << EOF > welcome.txt\nName: $name\nRoom: 2115\nEOF\necho \"Wrote welcome.txt\"\n\n# <<- removes leading TABS, so the text can be indented inside an if.\nif [ \"$count\" -gt 5 ]; then\n\tcat <<- EOF\n\tBig class: $count students\n\tEOF\nfi\n\n# Any command that reads input can take a here document, like sort.\nsort << EOF\nNoah\nAva\nMaya\nEOF\n\n# <<< (a here string) sends a single line.\nwc -w <<< \"So What Take Five\"","summary":"A here document (<< EOF) feeds several lines of text to a command, right from your script. Use it to print a block of text, write a file, or give input to a command without a separate file.","notes":["The ending marker must be alone on its line with nothing before or after it, not even spaces. EOF is a tradition; any word works.","With << 'EOF' in quotes, bash does not fill in $5 or $name, so the text prints exactly as written.","<<- only removes tab characters. If your editor turns tabs into spaces, the EOF line is not found."],"pitfall":"If the closing EOF is indented with spaces or misspelled, bash reads to the end of the file and warns here-document at line 8 delimited by end-of-file (wanted `EOF'). Everything after it becomes text instead of commands.","keywords":["here document","heredoc","<<","<<-","EOF","here string","<<<","multi-line text","write file","cat <<"],"stdin":"","output":"student@linux:~$ ./welcome.sh Leo\nWelcome to CS, Leo!\nStudents on the roster: 10\nFirst file to open: cs/hello.py\nLab fee: $5. Type $name in your own script to use a variable.\nWrote welcome.txt\nBig class: 10 students\nAva\nMaya\nNoah\n4\nstudent@linux:~$ cat welcome.txt\nName: Leo\nRoom: 2115","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"welcome.sh"},"strict-mode":{"code":"#!/bin/bash\n# Usage: ./archive.sh FOLDER\n# -e: stop at the first command that fails.\n# -u: stop if the script uses a variable that was never set.\n# -o pipefail: a pipeline fails if ANY command in it fails, not only the last.\nset -euo pipefail\n\ntmp=\"archive-tmp\"\n\n# trap ... EXIT runs cleanup when the script ends, for any reason.\ncleanup() {\n  if [ -d \"$tmp\" ]; then\n    rm -r \"$tmp\"\n    echo \"Cleanup: removed $tmp\"\n  fi\n}\ntrap cleanup EXIT\n\n# -u: with no argument, $1 is unset and the script stops here.\nfolder=\"$1\"\nmkdir \"$tmp\"\n\n# pipefail: if ls fails, this line fails, instead of wc reporting 0 items.\ncount=$(ls \"$folder\" | wc -l)\necho \"$folder has $count items\"\n\ncp -r \"$folder\" \"$tmp/\"\n# -e: if the folder has no README.md, cp fails and the script stops here.\ncp \"$folder/README.md\" \"$tmp/\"\necho \"Archive of $folder is ready\"","summary":"By default bash keeps going after an error, which can turn one mistake into many. set -euo pipefail makes a script stop at the first problem, and trap ... EXIT runs cleanup code however the script ends.","notes":["Each run that got as far as mkdir prints Cleanup: removed archive-tmp, and the ls afterward shows no archive-tmp folder. The EXIT trap ran even when the script stopped early.","The last line runs the same pipe at the prompt, where pipefail is off: ls fails, wc prints 0, and the exit code is 0, so the failure is hidden.","With no argument, the script stops at folder=\"$1\" before mkdir, so cleanup has nothing to remove and prints nothing."],"pitfall":"With -e and pipefail, a grep that finds nothing exits 1 and stops the script, as in count=$(grep ERROR notes.txt | wc -l). Add || true after a command that is allowed to fail.","keywords":["set -e","set -u","set -o pipefail","set -euo pipefail","strict mode","trap","EXIT","cleanup","unbound variable","errexit","nounset","error handling"],"stdin":"","output":"student@linux:~$ ./archive.sh cs/project\ncs/project has 2 items\nArchive of cs/project is ready\nCleanup: removed archive-tmp\nstudent@linux:~$ ./archive.sh music\nmusic has 1 items\ncp: cannot stat 'music/README.md': No such file or directory\nCleanup: removed archive-tmp\nstudent@linux:~$ ./archive.sh games\nls: cannot access 'games': No such file or directory\nCleanup: removed archive-tmp\nstudent@linux:~$ ./archive.sh\n./archive.sh: line 20: $1: unbound variable\nstudent@linux:~$ ls\narchive.sh  cs\tlogs  music  notes.txt\nstudent@linux:~$ ls games | wc -l; echo \"Exit code: $?\"\nls: cannot access 'games': No such file or directory\n0\nExit code: 0","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"archive.sh"},"arrays":{"code":"#!/bin/bash\n# An array holds a list of values. Quotes keep \"So What\" as one item.\nsongs=(\"So What\" \"Take Five\" \"Blue in Green\")\n\n# Indexes start at 0.\necho \"First song: ${songs[0]}\"\necho \"Song count: ${#songs[@]}\"\n\n# += adds to the end.\nsongs+=(\"Footprints\")\necho \"Last song: ${songs[-1]}\"\n\n# \"${songs[@]}\" in double quotes gives each item as one word.\nfor song in \"${songs[@]}\"; do\n  echo \"- $song\"\ndone\n\n# Without quotes, items split at spaces: 4 songs become 8 words.\nwords=0\nfor w in ${songs[@]}; do\n  words=$((words + 1))\ndone\necho \"Unquoted loop ran $words times\"\n\n# ${!songs[@]} lists the indexes, for a numbered list.\nfor i in \"${!songs[@]}\"; do\n  echo \"$((i + 1)). ${songs[i]}\"\ndone\n\n# An index that was never set is empty, not an error.\necho \"Song 10: '${songs[9]}'\"\n\n# mapfile reads a file into an array, one line per item.\nmapfile -t roster < cs/roster.txt\necho \"Roster size: ${#roster[@]}\"\n# ${roster[@]:0:3} is a slice: 3 items starting at index 0.\necho \"First three: ${roster[@]:0:3}\"\n\n# declare -A makes an associative array: names as keys instead of numbers.\ndeclare -A scores\nscores[Maya]=92\nscores[Leo]=78\nscores[Ava]=88\necho \"Leo's score: ${scores[Leo]}\"\n# Keys come back in no fixed order, so sort them for a stable list.\nfor name in $(printf '%s\\n' \"${!scores[@]}\" | sort); do\n  echo \"$name: ${scores[$name]}\"\ndone","summary":"An array stores a list of values in one variable. Bash has indexed arrays (numbered from 0) and associative arrays (looked up by a name).","notes":["${#songs[@]} is the number of items. ${songs[-1]} is the last item.","\"${songs[@]}\" with double quotes is the safe way to loop. It keeps \"Blue in Green\" together as one item.","Associative arrays need declare -A first. Without it, bash treats Maya as the number 0 and every name writes to the same slot."],"pitfall":"$songs without an index is only the first item, So What. Use \"${songs[@]}\" for all items and ${#songs[@]} for the count.","keywords":["array","arrays","list","${array[@]}","${#array[@]}","index","mapfile","readarray","declare -A","associative array","dictionary","+=","slice"],"stdin":"","output":"student@linux:~$ ./playlist.sh\nFirst song: So What\nSong count: 3\nLast song: Footprints\n- So What\n- Take Five\n- Blue in Green\n- Footprints\nUnquoted loop ran 8 times\n1. So What\n2. Take Five\n3. Blue in Green\n4. Footprints\nSong 10: ''\nRoster size: 10\nFirst three: Maya Leo Ava\nLeo's score: 78\nAva: 88\nLeo: 78\nMaya: 92","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"script","filename":"playlist.sh"},"path-aliases":{"code":"# PATH is the list of folders bash searches for commands, separated by colons.\necho $PATH\n# Make your own command: a script in ~/bin.\nmkdir -p ~/bin\nprintf '#!/bin/bash\\necho \"Today: CS quiz on loops\"\\n' > ~/bin/agenda\nchmod +x ~/bin/agenda\n# ~/bin is not in PATH yet, so bash cannot find agenda.\nagenda\n# Add ~/bin to the front of PATH for this session.\nexport PATH=\"$HOME/bin:$PATH\"\nagenda\n# which shows the folder a command was found in.\nwhich agenda\n# An alias is a short name for a longer command. Aliases are off in scripts,\n# and this page runs your commands from a script, so turn them on first.\nshopt -s expand_aliases\nalias ll='ls -l'\nll music\n# type also explains built-in commands and aliases.\ntype ll","summary":"When you type a command, bash looks for it in each folder listed in PATH. Add a folder to PATH to run your own scripts by name, and use alias to give a long command a short name.","notes":["export PATH=\"$HOME/bin:$PATH\" puts ~/bin first and keeps every folder that was already there. It lasts until you close the terminal. Add the line to ~/.bashrc to keep it.","Aliases also last only for this session. Put alias ll='ls -l' in ~/.bashrc so every new terminal has it.","shopt -s expand_aliases is only needed because this page runs your commands from a script. In a terminal you type in, aliases work without it."],"pitfall":"export PATH=\"$HOME/bin\" without :$PATH replaces the whole list, and then even ls fails with ls: command not found. Close the terminal and open a new one to get the old PATH back.","keywords":["PATH","$PATH","which","type","alias","unalias","~/.bashrc","export","command not found","~/bin","shopt","expand_aliases"],"stdin":"","output":"student@linux:~$ echo $PATH\n/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin\nstudent@linux:~$ mkdir -p ~/bin\nstudent@linux:~$ printf '#!/bin/bash\\necho \"Today: CS quiz on loops\"\\n' > ~/bin/agenda\nstudent@linux:~$ chmod +x ~/bin/agenda\nstudent@linux:~$ agenda\nbash: agenda: command not found\nstudent@linux:~$ export PATH=\"$HOME/bin:$PATH\"\nstudent@linux:~$ agenda\nToday: CS quiz on loops\nstudent@linux:~$ which agenda\n/home/student/bin/agenda\nstudent@linux:~$ shopt -s expand_aliases\nstudent@linux:~$ alias ll='ls -l'\nstudent@linux:~$ ll music\ntotal 4\n-rw-r--r-- 1 student student 123 Sep  8 08:15 playlist.txt\nstudent@linux:~$ type ll\nll is aliased to `ls -l'","run":true,"shot":null,"shot_note":"","setup_note":"","preview_height":null,"mode":"session","filename":null}}}};
